export const orderingMeta={slug:'algorithms/ordering',title:'Ordering, Heaps, and Selection',description:'Match full order, rank and dynamic frontiers to insertion/merge/partition sorting, bounded heaps, quickselect, sorted streams and median invariants.',date:'2026-04-08',updated:'2026-10-18',topicPath:['algorithms'],tags:['sorting','heap','priority queue','top k','quickselect','three-way partition','k-way merge','median','lazy deletion'],learningGoals:['Choose between sorting, selection and a dynamic frontier.','Track partition, heap and two-half invariants.','State rank, duplicates, mutation and complexity conditions.'],prototype:true,visibility:'public',kind:'dense-topic',related:['algorithms/binary-search','algorithms/graphs','algorithms/greedy']};
