function quickBody(f){return `${cells(f.values,(f.stage==='initial'||f.stage==='choose'?f.candidates:[f.i,f.j,f.pivotIndex]).filter(i=>i!==null&&i>=0&&i<f.values.length),f.rank===null?[]:[f.rank])}<p>Stage: ${f.stage}. ${f.message}</p><p>Pivot: ${f.pivot===null?'not selected':f.pivot}; pivot index: ${f.pivotIndex===null?'none':f.pivotIndex}; i=${f.i}, j=${f.j}.</p><p>${f.pivot===null?'The pivot has not been selected. No partition boundary is established.':f.rank===null?'During scanning, values before i (excluding the pivot) are at most the pivot; values after j are at least the pivot. The middle range remains unclassified.':'Values left of rank '+f.rank+' are at most '+f.pivot+'; values right are at least '+f.pivot+'. The outlined pivot is placed, not evidence that either side is sorted.'}</p><p>Outlines locate the pivot and scan indices. A scan index outside the array has no outlined cell. Candidate indices are ${f.candidates.join(', ')}; these are only three samples.</p>`;}
function sortMergeBody(f){return `<p>Stage: ${f.stage}. ${f.message}</p><div class="merge-sort-runs">${f.runs.map((run,i)=>`<figure><figcaption>Run ${i}${f.pair===i?' · left input':f.pair===i-1?' · right input':''}</figcaption>${run.length?cells(run.map(r=>r.value),f.pair===i||f.pair===i-1?[0]:[]):'<p>Exhausted</p>'}</figure>`).join('')}</div>${f.pair!==null?`<figure><figcaption>New sorted output</figcaption>${f.output.length?cells(f.output.map(r=>r.value)): '<p>Empty before the first move</p>'}</figure>`:''}<p>Remaining runs plus the separate output contain every input occurrence exactly once. Positions above cells are local to each remaining run, not original array indices. Outlines mark the next eligible heads.</p>`;}
const topFrames=topKTrace([5,1,8,3,9],3),selectFrames=threeWaySelectTrace([3,2,3,1,5,3,4],3),streamFrames=mergeStreamsTrace([[1,4],[1,3,8],[2,5]]),medianFrames=medianTrace([5,1,8,3,9,2]);
function topBody(f){const positions=[{x:250,y:50},{x:120,y:180},{x:380,y:180}],nodes=f.heap.map((v,i)=>({...positions[i],name:String(v)})),edges=nodes.slice(1).map((_,j)=>[Math.floor(j/2),j+1]);return `${cells(f.input,f.index===null?[]:[f.index],Array.from({length:f.processed},(_,i)=>i))}${nodes.length?graphSvg(nodes,edges):'<p>The retained heap is empty.</p>'}<p>${f.message}</p><p>Heap-array slots: [${f.heap.join(', ')}]. Retained count ${f.heap.length}; ${f.heap.length===3?'third-largest so far: '+f.heap[0]:'fewer than three inputs: rank answer is not available yet'}.</p><p>Tree labels are retained values; array order is not sorted order. Eviction removes one occurrence, so duplicates can occupy several ranks.</p>`;}
function partitionBody(f){const active=f.pivot===null?[]:[f.i].filter(i=>i<=f.gt),done=f.pivot===null?[]:Array.from({length:Math.max(0,f.gt-f.lt+1)},(_,i)=>i+f.lt).filter(i=>i<f.i);return `${cells(f.values,active,done)}<p>${f.message}</p><p>Target k=${f.k}, active bounds [${f.lo},${f.hi}], pivot ${f.pivot===null?'not chosen':f.pivot}.</p>${f.pivot===null?'':`<p>Within the active bounds: less [${f.lo},${f.lt}); equal [${f.lt},${f.i}); unknown [${f.i},${f.gt+1}); greater [${f.gt+1},${f.hi+1}). Empty ranges contain no values.</p>`}<p>${f.answer===null?'The full array is not being sorted.':'Selected value: '+f.answer+'. Equal values occupy several sorted ranks; the requested rank is inside that block.'}</p><p>Blue fill marks the established equal region, and the outline marks the current unknown position when one remains. Numeric boundaries identify all four regions.</p>`;}
function streamBody(f){return `<div class="stream-frontiers">${f.streams.map((s,i)=>`<div><b>Source ${i}</b>${cells(s,f.positions[i]<s.length?[f.positions[i]]:[],Array.from({length:f.positions[i]},(_,j)=>j))}</div>`).join('')}</div><p>${f.message}</p><p>Output prefix: [${f.output.join(', ')}]. Heap-array frontier: ${f.heap.length?f.heap.map(j=>`(${j.value},source ${j.source},index ${j.index})`).join(' · '):'empty'}.</p><p>At most one unconsumed head per nonempty source is present. Blue fill marks emitted source positions, not a globally sorted source-index order.</p>`;}
function medianBody(f){return `${cells(f.input,f.index===null?[]:[f.index],Array.from({length:f.count},(_,i)=>i))}<div class="scene-grid"><figure><figcaption>Lower half — max-heap; root first</figcaption>${cells(f.lower)}<p>Maximum: ${f.lower.length?f.lower[0]:'none'}.</p></figure><figure><figcaption>Upper half — min-heap; root first</figcaption>${cells(f.upper)}<p>Minimum: ${f.upper.length?f.upper[0]:'none'}.</p></figure></div><p>${f.message}</p><p>Stage: ${f.stage}. Sizes ${f.lower.length}/${f.upper.length}. Median: ${f.median===null?(f.count?'query at the next validated state':'undefined for empty stream'):f.median}.</p><p>These are actual heap-array orders, not sorted lists. The lower side must have the same size as upper or one more. Median queries occur only at balanced states.</p>`;}
function insertionBody(f){const end=f.sortedLength+(f.held?1:0),active=[f.gap,f.compare].filter(i=>i!==null),done=Array.from({length:end},(_,i)=>i).filter(i=>f.records[i]);return `${cells(f.values,active,done)}<p>Held value: ${f.held?f.held.value+' (original index '+f.held.id+')':'none'}. Gap: ${f.gap===null?'none':f.gap}. Stage: ${f.stage}.</p><p>${f.message}</p><p>A dash is the empty slot, not a zero. The held value plus all occupied slots preserve every input occurrence. Blue fill marks the ordered run; outlines identify the gap or comparison. Shift only values strictly larger than the held value, then place it in the gap.</p>`;}
export function orderingReader(link){return topic(orderingMeta,orderingSections,'Full order, one rank and a changing frontier are different requests.',`
<p>Ordering algorithms make different promises. A sort orders every record. Selection finds a requested rank without ordering the rest. A priority queue repeatedly returns the best currently available candidate while the set changes.</p><p>Start with that promise. Then state how ties, duplicate occurrences, input mutation and payload comparisons work. The same numeric values can require a different structure when the operation changes.</p>
${section('objective','How much order does the query need?',`${table('Match the query to maintained information',['Query','Useful structure','What remains unordered'],[['One minimum/maximum now','Linear scan','Every other value'],['All records in order','Sorting','Nothing under the chosen key'],['One rank in a fixed array','Quickselect','Values within the discarded/retained sides'],['Top k while values arrive','Bounded heap','Retained values except root ordering'],['Next smallest from sorted sources','Heap of current heads','Later source values are not yet candidates'],['Running median','Two heaps','Interior of each half']])}<p>A heap can produce full order by repeated extraction, but it does not store that order at rest. Do not read its array as a sorted list. Conversely, a one-time sort can be simpler when the data will not change and many rank queries follow.</p><p>Define a consistent comparison key. Equal-key records may be interchangeable for one query and require stable arrival order for another. Values such as NaN need an explicit policy because ordinary numeric comparisons do not supply the assumed order.</p>`)}
${section('insertion','Insert into a sorted prefix',`<p>Insertion sort keeps the processed prefix sorted. Take the next value, move larger prefix values right and put the value into the resulting gap.</p><pre tabindex="0" role="region" aria-label="Insertion sort Python"><code>def insertion_sort(values):
    for i in range(1, len(values)):
        current = values[i]
        j = i - 1
        while j &gt;= 0 and values[j] &gt; current:
            values[j + 1] = values[j]
            j -= 1
        values[j + 1] = current
    return values</code></pre><p>This function mutates and returns the same list. Keys must supply a consistent order. Empty and singleton lists need no movement.</p><p>The strict comparison does not move an equal earlier value past the new value, so this version is stable. Its best case is linear on an already ordered array; reverse order requires quadratic shifts. It uses constant auxiliary storage when values are moved in place.</p><p>Nearby order matters: each shift removes an inversion, a pair that appears in the wrong relative order. Tiny or nearly ordered inputs can make insertion attractive without making it a good general quadratic sort for large arbitrary data. ${cite('https://algs4.cs.princeton.edu/21elementary/','Sorted-prefix invariant and inversion cost')}</p>`)}
${traceLab('insertion-lab','Hold one value while the gap moves','Input [6,5,3,1,8,7,2,4]. Hold the next value separately; shift larger values right, then place the held value. Final order is [1,2,3,4,5,6,7,8]. These are operation states, not measured timing.',insertionFrames,insertionFrames.length-1,insertionBody)}
${section('merge-sort','Merge ordered halves',`<p>Merge sort recursively orders both halves, then compares their current heads. The smaller head is the next output because every later value in either half is at least its own head. Exhausting one side leaves a suffix that can be copied directly.</p><p>The base case is a range of zero or one value, not necessarily a pair. Choosing the left head when keys tie preserves source order in the usual stable merge. Each level moves O(n) values, and there are O(log n) balanced splitting levels.</p><p>The usual array version costs O(n log n) time and O(n) auxiliary merge storage, plus recursion state. Bottom-up merging instead combines runs of length 1, then 2, 4 and so on. Variants can skip an already ordered boundary, but that optimization is not part of every implementation. ${cite('https://algs4.cs.princeton.edu/22mergesort/','Merge and evaluation order')}</p>`)}
${traceLab('merge-sort-lab','Split the ranges, then move only their heads','Input [6,5,3,1,8,7,2,4]. This level-wise teaching schedule shows all splits before merging adjacent runs. A recursive implementation can visit those operations in a different order.',sortMergeFrames,sortMergeFrames.length-1,sortMergeBody,'Run heads feed a separate output; playback is illustrative, not an in-place sorting implementation.')}
${table('The same values acquire order at each merge level',['Stage','Runs, in original left-to-right positions'],[['Input','[6,5,3,1,8,7,2,4]'],['Split into halves','[6,5,3,1] | [8,7,2,4]'],['Split into pairs','[6,5] | [3,1] | [8,7] | [2,4]'],['Singleton base cases','[6] | [5] | [3] | [1] | [8] | [7] | [2] | [4]'],['Merge pairs','[5,6] | [1,3] | [7,8] | [2,4]'],['Merge fours','[1,3,5,6] | [2,4,7,8]'],['Merge whole range','[1,2,3,4,5,6,7,8]']])}
<p>During the final merge, choose heads 1,2,3,4,5,6. The left run then empties, so copy the remaining right suffix 7,8. Every choice is local to two already sorted runs; no scan for the smallest remaining interior value is needed.</p>
${section('partition-sort','Partition before sorting both sides',`<p>Quicksort uses the opposite divide-and-conquer sequence: partition first, then sort the resulting sides. A pivot partitions values according to their relation to it. Partitioning is not itself a complete sort.</p><p>Different partition routines promise different boundaries. Lomuto moves a pivot to the end, scans values below it and places the pivot at one final rank. A crossing-pointer partition can return a split boundary instead. Read the routine's contract before using p−1/p+1 recursion bounds.</p><p>Duplicate keys can produce poor progress in a naive two-way scheme. Three-way partitioning establishes less-than, equal and greater-than regions. Quicksort then recurses only on the two unequal regions; every value in the equal block is already at an appropriate rank.</p><p>Balanced partitions produce O(n log n) work. Repeatedly removing one element produces O(n²) work and linear recursive depth. Random pivots reduce adverse-input dependence; they do not remove the worst case. Median-of-three and tiny-range insertion cutoffs are engineering choices, not universal speedup guarantees. ${cite('https://algs4.cs.princeton.edu/23quicksort/','Partition contracts and duplicate handling')}</p><p>Measured speed depends on implementation, key cost, memory access and input distribution. The older “two to three times faster than merge sort” statement is not a general property of quicksort.</p>`)}
${traceLab('quicksort-lab','Cross two scans, then place the pivot','Input [4,1,7,3,2,5,8,6]. Median-of-three chooses 4 from first 4, middle 3 and last 6. This first-pivot partition places 4 at rank 3, leaving [3,1,2] and [7,5,8,6] to sort.',quickFrames,quickFrames.length-1,quickBody,'One partition, not a whole quicksort. Moving scan indices immediately after a swap skips positions already classified.')}
${table('Two scans separate the sides before recursion',['Operation','Array and boundaries'],[['Choose pivot','[4,1,7,3,2,5,8,6]; pivot at index 0'],['Find wrong-side values','i=2 holds 7; j=4 holds 2'],['Swap those values','[4,1,2,3,7,5,8,6]'],['Cross the scans','i=4 holds 7; j=3 holds 3'],['Place pivot at j','[3,1,2,4,7,5,8,6]; rank 3'],['Recurse on both sides','Sort indices [0,2] and [4,7]; stop on zero or one value']])}
<p>The first-pivot variant finishes by swapping the pivot with j. Its final rank is excluded from both recursive calls. The animation's original example has distinct values. Here, equal scan values may be swapped and both indices advance. That explicit tie policy prevents an infinite loop; it does not create a three-way equal block.</p>
${table('A return value is meaningful only with its partition contract',['Variant','Pivot location during scan','Return value and recursive ranges'],[['First-pivot crossing scans above','First slot; i moves right and j left','Final pivot rank p; [lo,p−1] and [p+1,hi]'],['End-pivot crossing scans','Last slot; scan the preceding range','With bounded scans passing ≤ on left and > on right, swap pivot with i; final rank i'],['Strict Lomuto below','Last slot; one forward scan','Final pivot rank p; [lo,p−1] and [p+1,hi]'],['Hoare split-boundary variant','Pivot value; not necessarily placed finally','Split j; [lo,j] and [j+1,hi], with a shrinking-range contract']])}
<p>For the end-pivot variant, initialize i=lo and j=hi−1. Scan only while i≤j; pass values ≤pivot on the left and >pivot on the right. Swap an unclassified wrong-side pair, then advance both indices. At crossing, i=j+1; exchange values[i] with the pivot at hi. This preserves the earlier end-pivot explanation without pretending it is the first-pivot example above. All-equal data can still leave a side of size n−1. Median-of-three is a sample heuristic, not an exact median or a worst-case guarantee.</p>
${section('select','Select only the side containing the rank',`<p>Selection reuses partitioning but explores only the region containing the requested rank. Use zero-based k for the k-indexed smallest value. A one-based r-th largest query maps to k=n−r; duplicate occurrences count separately unless a distinct-value rank is requested.</p><pre><code># After partitioning active inclusive bounds [lo, hi]:
if k &lt; equal_start:
    hi = equal_start - 1
elif k &gt; equal_end:
    lo = equal_end + 1
else:
    return pivot</code></pre><p>Maintain an interval containing the desired global rank. Values discarded on the left belong before every remaining answer candidate; discarded right values belong after it. When k is inside the equal block, return its value without selecting among identical occurrences.</p><p>The original [3,2,1,5,4] example asks for k=1. Partitioning around 3 places it at rank 2; only the smaller side matters. Partitioning that side around 2 fixes rank 1 and returns 2.</p><p>Randomized selection has expected linear work under the standard pivot model and suitable equal-key handling. The illustrative n+n/2+n/4 sum assumes balanced progress; it is not a proof that every random step halves the input. Naive strict Lomuto partitioning on all-equal values can remain quadratic even with a random pivot.</p><p>Worst-case work is O(n²) for these simple pivot strategies. Iterative selection uses constant auxiliary state in-place; recursive depth can be O(n), not an unconditional O(log n). Deterministic median-of-medians can guarantee linear work but uses a different pivot procedure. The lab chooses the first active value for reproducibility, not as a recommended random policy.</p><p>Reject an empty array or out-of-range rank. Partitioning mutates the input; use a copy when caller order must survive. The implementation below keeps the same strict Lomuto partition, but uses an iterative selection loop to avoid recursion depth.</p>`)}
<details><summary>Implement a final-pivot-rank contract</summary><pre tabindex="0" role="region" aria-label="Lomuto partition Python"><code>def lomuto(values, left, right, pivot_index):
    pivot = values[pivot_index]
    values[pivot_index], values[right] = values[right], values[pivot_index]
    store = left
    for i in range(left, right):
        if values[i] &lt; pivot:
            values[store], values[i] = values[i], values[store]
            store += 1
    values[right], values[store] = values[store], values[right]
    return store</code></pre><pre tabindex="0" role="region" aria-label="Lomuto quickselect Python"><code>import random

def quickselect(values, k):
    if type(k) is not int or not 0 &lt;= k &lt; len(values):
        raise ValueError("k must be an integer in 0..n-1")
    left, right = 0, len(values) - 1
    while left &lt; right:
        pivot = lomuto(values, left, right, random.randint(left, right))
        if k == pivot:
            return values[pivot]
        if k &lt; pivot:
            right = pivot - 1
        else:
            left = pivot + 1
    return values[left]</code></pre><p>lomuto assumes valid inclusive bounds and a pivot index inside them. It moves strictly smaller values left and values greater than or equal right. quickselect mutates a list and counts duplicate occurrences separately. For [3,2,1,5,4,6] at k=3, it returns4. Random pivots do not guarantee linear work; equal values still cause poor Lomuto progress.</p></details>
${traceLab('partition-lab','Four partition regions become one selected value','Fixed input [3,2,3,1,5,3,4], k=3 (fourth smallest). Three equal 3s form one block, so the answer is 3 without sorting either side.',selectFrames,selectFrames.length-1,partitionBody)}
${section('heap','A heap orders parent–child paths, not siblings',`${eq("\\begin{aligned}\\operatorname{left}(i)&=2i+1,\\quad\\operatorname{right}(i)=2i+2\\\\\\operatorname{parent}(i)&=\\left\\lfloor\\frac{i-1}{2}\\right\\rfloor,\\quad i\\ge1\\\\a_{\\operatorname{parent}(i)}&\\le a_i,\\quad1\\le i<n\\end{aligned}","Zero-based complete-tree array with n entries. Child formulas give candidate indices; access only when below n. The root has no parent. The inequality is the min-heap invariant under a consistent comparison order, not full sibling/array ordering.")}<p>Every descendant of a min-heap root is reached through nondecreasing parent–child edges, so the root is a minimum. Siblings need not be ordered. A max-heap reverses the inequality and exposes a maximum.</p><p>Peek reads the root in O(1). Push adds a leaf and moves it upward while its parent is worse. Pop removes the root, moves the last leaf into that slot and moves it downward through the better child. Choose the better of both children, not just the first one.</p><p>Both repairs follow a path of height O(log n). The partially ordered tree is the data structure; the priority queue is the abstract insert/extract behavior it implements. An ordinary FIFO queue instead returns arrival order.</p>`)}
${section('heapify','Repair one path; build from the bottom',`<p>Repeated pushes build a heap in O(n log n) worst-case work. Bottom-up heapify starts from the last internal node and repairs downward. At each repair, both child subtrees are already heaps.</p>${eq("T_{\\mathrm{heapify}}=O\\!\\left(n+\\sum_{h=1}^{\\lfloor\\log_2 n\\rfloor}\\left\\lfloor\\frac{n}{2^h}\\right\\rfloor\\right)=O(n),\\qquad n\\ge1","Bottom-up repair in a complete binary heap with constant-cost comparisons and swaps. At most floor(n/2ʰ) nodes can move h or more levels. Summing these possible movements bounds total work; most nodes cannot traverse the full height. Empty input requires no repairs.")}<p>Heapify changes array order in place. Heapsort then repeatedly moves the extreme root to its final position and repairs the remaining heap. It is a way to produce full order, so “a heap is never used to sort” would be false. ${cite('https://algs4.cs.princeton.edu/24pq/','Repair paths and heap construction')}</p>`)}
${section('priority','Separate priority from payload and ties',`<p>Python heapq's ordinary operations use a min-heap. Numeric negation implements maximum-priority behavior on older versions. Python 3.14 added native functions such as heapify_max, heappush_max and heappop_max; choose an API supported by the runtime. ${cite('https://docs.python.org/3/library/heapq.html','Current heapq API')}</p><pre><code>from heapq import heappush, heappop
from itertools import count
queue, sequence = [], count()
heappush(queue, (priority, next(sequence), payload))
priority, arrival, payload = heappop(queue)</code></pre><p>This fragment assumes priority and payload exist. Tuples compare lexicographically. A unique sequence number breaks equal-priority ties without comparing arbitrary payload objects; it can also preserve arrival order among equal priorities.</p><p>Store (−frequency,value) when maximum frequency comes first and value is the intended tie key. Negating only a numeric priority does not negate a whole record's ordering policy. Do not silently let a payload's incidental comparison decide ties.</p><p>For numeric min-priority, the original [5,1,8,3] example heapifies the array, extracts1, inserts2 and exposes2 at the root. For numeric max-priority on older APIs, negate on insertion and negate again on reading or removal:</p><pre><code>values = [5, 1, 8, 3]
max_heap = [-x for x in values]
heapify(max_heap)
largest = -heappop(max_heap)  # 8
heappush(max_heap, -7)
top = -max_heap[0]  # 7</code></pre><p>This fragment assumes heapq functions were imported. An empty heap cannot be peeked or popped. Negation adapts numeric priorities; it does not reverse arbitrary payload comparisons. Ordinary min-heap insertion of5,2,8 produces extraction order2,5,8.</p><p>With (priority,task) pairs (2,“task-b”), (1,“task-a”), (3,“task-c”), the first extraction is (1,“task-a”). Using (−10,“urgent”) and (−3,“normal”) instead selects urgent first; negate the returned numeric key to recover its positive priority. Equal numeric keys fall through to later tuple fields, so use the unique arrival counter above when payloads are dictionaries or other noncomparable objects.</p><p>heappushpop adds a value then removes the minimum. heapreplace removes the current minimum then adds a value, even when that new value is smaller. For retaining larger candidates, unconditional heapreplace can therefore evict a better value. Use an explicit boundary check or the push/pop policy appropriate to the objective.</p>`)}
${section('top-k','Expose the weakest retained candidate',`<p>To keep the k largest seen values, use a min-heap of at most k. Its minimum is the weakest retained candidate. Add a new value and remove the minimum if capacity is exceeded.</p><pre tabindex="0" role="region" aria-label="Largest k Python"><code>from heapq import heappush, heappop
def largest_k(values, k):
    if type(k) is not int or not 0 &lt;= k &lt;= len(values):
        raise ValueError("k outside 0..n")
    heap = []
    for value in values:
        heappush(heap, value)
        if len(heap) &gt; k:
            heappop(heap)
    return heap  # Retained, but not sorted.</code></pre><details><summary>Query a rank or change the priority to frequency</summary><pre tabindex="0" role="region" aria-label="Kth largest Python"><code>def kth_largest(values, rank):
    if type(rank) is not int or not 1 &lt;= rank &lt;= len(values):
        raise ValueError("rank must be an integer in 1..n")
    return largest_k(values, rank)[0]</code></pre><pre tabindex="0" role="region" aria-label="Top frequency Python"><code>from collections import Counter
from heapq import heappush, heappop

def top_k_frequent(values, k):
    counts = Counter(values)
    if type(k) is not int or not 0 &lt;= k &lt;= len(counts):
        raise ValueError("k must be an integer in 0..distinct count")
    heap = []
    for value, frequency in counts.items():
        heappush(heap, (frequency, value))
        if len(heap) &gt; k:
            heappop(heap)
    return [value for frequency, value in heap]</code></pre><p>The rank wrapper uses largest_k above. Frequency keys must be hashable and mutually ordered. Larger values win equal-frequency eviction ties; the output is not sorted. Use an explicit serial/key policy instead for noncomparable payloads.</p></details><p>After t inputs, the heap contains the min(k,t) largest occurrences of that prefix. Removing the smallest among k+1 candidates preserves that invariant. Once k values exist, the root is the kth largest; before then that rank is undefined.</p><p>For k smallest, reverse the heap direction so the largest retained value is easiest to evict. k=0 returns an empty selection, but a kth-element query needs 1≤k≤n. Sorting the final heap into rank order is additional work.</p><p>A numeric stream costs O(n log(max(2,k))) work and O(k) auxiliary storage. Top-frequency selection first counts distinct values: with m distinct keys, include O(m) count storage and the input counting cost before the m candidate heap updates. A frequency bucket can be another option under the count-domain contract; a heap is not always best.</p>`)}
${traceLab('top-k-lab','The root is the eviction boundary','Keep the three largest occurrences of [5,1,8,3,9]. Final heap [5,9,8] retains 5,8,9; its root 5 is the third largest.',topFrames,topFrames.length-1,topBody)}
${section('streams','One head per sorted source',`<p>Each nonempty sorted source contributes its first unconsumed value. Every later value in that source is at least this head. Therefore the smallest remaining value overall must be one of the current heads.</p><pre tabindex="0" role="region" aria-label="K way merge Python"><code>from heapq import heappush, heappop

def merge_k_sorted_lists(streams):
    heap, output = [], []
    for source, values in enumerate(streams):
        if values:
            heappush(heap, (values[0], source, 0))
    while heap:
        value, source, index = heappop(heap)
        output.append(value)
        next_index = index + 1
        if next_index &lt; len(streams[source]):
            heappush(heap, (streams[source][next_index], source, next_index))
    return output</code></pre><p>The function assumes sorted, indexable finite sequences with mutually comparable values. It does not mutate the sources and returns a new list. Empty sources contribute no head. After extraction, advance only the source that supplied the value. Source/index metadata identifies that successor and gives deterministic tie handling.</p><p>For N outputs and K input sources, heapify initialization and extraction cost O(K+N log(max(2,K))) with O(K) frontier storage. Empty sources still require inspection. Materializing the output adds O(N) space; yielding it avoids that retained output. The original repeated-push initialization has its own K log K setup cost.</p><p>The same frontier can stop at a requested rank. To find a smallest range containing one value from every source, track the largest current head alongside the smallest. Evaluate their range, then advance the minimum's source; exhaustion of any required source ends complete coverage. The objective is no longer to emit all values.</p><p>For linked nodes, store a comparable key and source/tie metadata, not arbitrary nodes in an unqualified equal-key tuple. Preserve node ownership when rewiring; <a href="${link('algorithms/linked-lists')}">linked-list ownership →</a> owns that distinction.</p>`)}
${traceLab('stream-lab','Advance only the source that supplied the minimum','Sorted sources [1,4], [1,3,8], [2,5]. Equal heads use source index as the tie key. Final output is [1,1,2,3,4,5,8].',streamFrames,streamFrames.length-1,streamBody)}
${section('median','Keep both boundaries of the middle',`<p>Split observed values into lower and upper halves. A max-heap exposes the lower maximum; a min-heap exposes the upper minimum. Use two independent invariants: every lower value ≤ every upper value, and lower has either the same number of values or one more.</p><p>Insert on the side determined by the lower maximum. If the size invariant fails, move one boundary value across. Moving lower's maximum to upper or upper's minimum to lower preserves cross-half ordering. Read the median only after these repairs.</p>${eq("\\operatorname{median}=\\begin{cases}\\max(L),&n\\text{ odd},\\\\\\dfrac{\\max(L)+\\min(U)}{2},&n\\text{ even}.\\end{cases}","For n ≥ 1 retained values, every value of lower half L is at most every value of upper half U. L has either equal size or one extra. Query only after both invariants hold; the even case has two nonempty halves. This convention averages middle values; guard arithmetic overflow.")}<p>The original implementation uses negative values for the lower max-heap. It first inserts on lower, repairs cross-half order, then repairs sizes. The lab chooses the ordered side before rebalancing. Both approaches require both invariants; the update order is part of the implementation.</p><details><summary>Implement insert, order repair, then size repair</summary><pre tabindex="0" role="region" aria-label="Running median Python"><code>from heapq import heappush, heappop
from fractions import Fraction

class MedianFinder:
    def __init__(self):
        self.small, self.large = [], []
    def addNum(self, value):
        heappush(self.small, -value)
        if self.large and -self.small[0] &gt; self.large[0]:
            heappush(self.large, -heappop(self.small))
        if len(self.small) &gt; len(self.large) + 1:
            heappush(self.large, -heappop(self.small))
        elif len(self.large) &gt; len(self.small):
            heappush(self.small, -heappop(self.large))
    def findMedian(self):
        if not self.small:
            raise ValueError("median is undefined for an empty stream")
        if len(self.small) &gt; len(self.large):
            return -self.small[0]
        return Fraction(-self.small[0] + self.large[0], 2)</code></pre><p>This class accepts integers under its caller contract. Negation keeps compatibility with older heap APIs. The even case returns an exact Fraction rather than rounding through float; convert explicitly only if a floating result is wanted. Each instance owns its heaps.</p></details><p>Insert costs O(log n), query O(1), retained values O(n). For exact integer arithmetic, the even answer may be a half-integer. Large fixed-width values need an overflow-safe average; floating-point implementations still have representation limits.</p><p>A sliding median additionally deletes outgoing occurrences. Size counts must track logical active values, not stale physical entries. Prune invalid roots before comparisons, moves and queries. <a href="${link('algorithms/windows')}">Sliding-window contracts →</a> determine which occurrence leaves.</p>`)}
${traceLab('median-lab','Query only after the two invariants hold','Stream [5,1,8,3,9,2]. Insertion can temporarily violate the size rule. Balanced-prefix medians are 5,3,5,4,5,4.',medianFrames,medianFrames.length-1,medianBody)}
${section('lazy','Invalid entries are not active work',`<p>A plain heap does not cheaply find an arbitrary payload to delete or update. Maintain an external identity/version map or deletion count, leave old entries physically stored and discard them when they reach the root.</p><p>Changing a priority in place can break heap order. Push a new version instead and mark the old version invalid. Before returning a root, verify that its identity/version is still active. Duplicate numeric values may require occurrence identifiers or counts; a single set of values can discard the wrong copy.</p><p>Stale entries can increase physical memory beyond the active queue size. Include their insertion/removal costs in accounting; rebuild from active entries when the application needs bounded memory. A bounded active set alone does not bound a lazy heap's physical size.</p><p>In <a href="${link('algorithms/graphs#dijkstra')}">Dijkstra →</a>, an old distance entry becomes stale after improvement. First insertion does not finalize a distance. In <a href="${link('algorithms/greedy#rooms')}">room counting →</a>, the heap holds active finish events, not generic available work. A heap supplies order; correctness comes from the owning algorithm's state meaning.</p>`)}
${section('choice','Costs follow the operation and the contract',`${contractTable('Choose an algorithm with its real guarantees',['Method','Time','State/conditions'],[['Insertion sort','Best O(n), worst O(n²)','In-place; strict-shift version stable'],['Array merge sort','O(n log n) standard worst case','O(n) merge buffer; tie policy for stability'],['Simple quicksort','Expected O(n log n), worst O(n²)','Pivot/equal-key assumptions; recursive stack can be O(n)'],['Simple quickselect','Expected O(n), worst O(n²)','One requested rank; appropriate duplicate handling'],['Binary heap','Peek O(1), push/pop O(log n)','Array not fully sorted; payload comparison contract'],['Bottom-up heapify','O(n)','Existing array; mutates its order'],['Bounded top k','O(n log(max(2,k)))','O(k) auxiliary; returned heap unordered'],['Sorted-source frontier','O(K+N log(max(2,K))) with heapify','O(K) auxiliary; output memory separate'],['Two-heap median','Insert O(log n), query O(1)','O(n) retained input values; order and size invariants']])}<p>Test empty/singleton data, all equal values, already sorted and reverse order, negative values, ${inlineMath(String.raw`k=0`)} or ${inlineMath(String.raw`k=n`)}, exhausted sources and equal-priority noncomparable payloads. Compare small selections and prefix medians with full sorting; check intermediate invariants as well as final answers.</p><p><a href="${link('algorithms/binary-search')}">Binary search →</a> benefits from a full sorted order or a monotone predicate. <a href="${link('algorithms/graphs')}">Graph algorithms →</a> use ordered frontiers for weighted paths and spanning trees. The structure is shared, but neither objective follows from the heap alone.</p>`)}
${section('sources','Sources and related mechanisms',`<p>${cite('https://docs.python.org/3/library/heapq.html','Python heapq operations and API conditions')} · ${cite('https://algs4.cs.princeton.edu/23quicksort/','Partitioning variants')} · ${cite('https://algs4.cs.princeton.edu/25applications/','Selection by rank')} · ${cite('https://www.youtube.com/watch?v=kp3fCihUXEg&t=48s','Original mixed-note video reference')}</p><p><a href="${link('algorithms/binary-search#exact-lab')}">Exact binary-search walkthrough →</a> · <a href="${link('algorithms/trees#dfs-walk')}">DFS and BFS frontiers →</a> · <a href="${link('algorithms/greedy#commit')}">When local cost fails →</a></p><p>The traces are exact small synthetic inputs, not empirical speed comparisons. The callable pattern examples above include their initialization and answer query.</p>`)}
`);}
